script.setup:
// TactileJS describes the 81 isohedral tiling types: it gives the tile's edges (and which
// edges must match), places the copies over the plane and colours them. The scene bends the edges
// with animated Bezier curves, so the tile shape keeps changing while still tiling the plane.
const { IsohedralTiling, tilingTypes, EdgeShape, mul } = await ctx.utils.import("https://esm.sh/tactile-js@1.0.0");
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
Object.assign(s, { kit, IsohedralTiling, tilingTypes, EdgeShape, mul, type: -1, tiling: null, base: null });
s.show = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_fill;
void main(){
  vec4 t = texture(u_fill, v_uv);
  // Tiles don't overlap, so colour / coverage gives each tile its own colour.
  vec3 c = abs(t.a) > 1e-3 ? t.rgb / t.a : vec3(0.0);
  outColor = vec4(c * min(abs(t.a), 1.0), 1.0);
}`);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit, ES = s.EdgeShape, mul = s.mul;
const [w, h] = ctx.resolution, t = ctx.time * u.u_speed;
const n = s.tilingTypes.length;
const type = u.u_auto ? (Math.floor(ctx.time / 6) * 7 + u.u_type) % n : u.u_type % n;
if (type !== s.type) {
  s.type = type;
  s.tiling = new s.IsohedralTiling(s.tilingTypes[type]);
  s.base = s.tiling.getParameters();
  s.phases = Array.from({ length: 16 }, () => [Math.random() * 6.283, Math.random() * 6.283, 0.5 + Math.random()]);
}
const tiling = s.tiling;
// Breathe the tiling's own parameters (vertex positions) a little around their defaults.
if (s.base.length) tiling.setParameters(s.base.map((v, i) => v + Math.sin(t * 0.7 + i * 1.7) * 0.08 * u.u_wild));
// Edge curves, with the symmetry each edge shape requires (J: any, U: mirror, S: point, I: straight).
const edges = [];
for (let i = 0; i < tiling.numEdgeShapes(); i++) {
  const shp = tiling.getEdgeShape(i), [p1, p2, f] = s.phases[i % 16];
  const a = { x: 0.3 + 0.15 * Math.sin(t * f + p1), y: u.u_wild * Math.sin(t * 0.9 * f + p2) };
  if (shp === ES.I) edges.push(null);
  else if (shp === ES.J) edges.push([a, { x: 0.7 + 0.15 * Math.cos(t * f + p2), y: u.u_wild * Math.cos(t * 0.8 * f + p1) }]);
  else if (shp === ES.S) edges.push([a, { x: 1 - a.x, y: -a.y }]);
  else edges.push([a, { x: 1 - a.x, y: a.y }]);
}
// One tile outline in tiling coordinates.
const outline = [];
for (const part of tiling.shape()) {
  const ej = edges[part.id];
  let seg = [mul(part.T, { x: 0, y: 0 })];
  if (ej) seg.push(mul(part.T, ej[0]), mul(part.T, ej[1]));
  seg.push(mul(part.T, { x: 1, y: 0 }));
  if (part.rev) seg = seg.reverse();
  const steps = ej ? 10 : 1;
  for (let k = 0; k < steps; k++) {
    const q = k / steps, m = 1 - q;
    if (!ej) { outline.push(seg[0].x, seg[0].y); continue; }
    outline.push(m * m * m * seg[0].x + 3 * m * m * q * seg[1].x + 3 * m * q * q * seg[2].x + q * q * q * seg[3].x,
      m * m * m * seg[0].y + 3 * m * m * q * seg[1].y + 3 * m * q * q * seg[2].y + q * q * q * seg[3].y);
  }
}
// Screen transform: scale and a slow pan.
const S = h * u.u_scale, ox = w / 2 + Math.sin(t * 0.13) * S * 2, oy = h / 2 + t * S * 0.15;
const pal = [u.u_color1, u.u_color2, u.u_color3];
const [mx, my] = ctx.mouse, mp = [mx * w, (1 - my) * h];
s.moved ||= mx !== 0.5 || my !== 0.5;
const inside = (ring, x, y) => {
  let c = false;
  for (let i = 0, j = ring.length - 2; i < ring.length; j = i, i += 2)
    if ((ring[i + 1] > y) !== (ring[j + 1] > y) && x < (ring[j] - ring[i]) * (y - ring[i + 1]) / (ring[j + 1] - ring[i + 1]) + ring[i]) c = !c;
  return c;
};
const fills = [], lines = [];
const lw = Math.max(1, h * 0.0025);
let tiles = 0, hover = null;
for (const inst of tiling.fillRegionBounds((-ox) / S - 2, (-oy) / S - 2, (w - ox) / S + 2, (h - oy) / S + 2)) {
  const T = inst.T, ring = new Array(outline.length);
  for (let i = 0; i < outline.length; i += 2) {
    const x = T[0] * outline[i] + T[1] * outline[i + 1] + T[2], y = T[3] * outline[i] + T[4] * outline[i + 1] + T[5];
    ring[i] = x * S + ox; ring[i + 1] = y * S + oy;
  }
  const c = pal[tiling.getColour(inst.t1, inst.t2, inst.aspect) % 3];
  // A little per-tile variation in brightness.
  const v = 0.85 + 0.15 * Math.sin(inst.t1 * 1.7 + inst.t2 * 2.3 + inst.aspect);
  const lit = s.moved && !hover && inside(ring, mp[0], mp[1]);
  if (lit) hover = ring;
  const k = lit ? 1.35 : v;
  kit.fan(ring, [c[0] * k, c[1] * k, c[2] * k, 1], fills);
  kit.line(ring, true, lw, [0.06, 0.06, 0.08, 1], lines);
  tiles++;
}
if (hover) kit.line(hover, true, lw * 2.5, [1, 1, 1, 1], lines);
const tex = kit.accumulate(fills);
gl.useProgram(s.show);
ctx.utils.bindTexture(s.show, "u_fill", tex, 0);
ctx.utils.drawFullscreen(s.show);
kit.draw(lines);
ctx.publish("tiling type", "IH" + String(s.tilingTypes[type]).padStart(2, "0"));
ctx.publish("tiles", tiles);
